#X3D V4.1 utf8 X_ITE V16.5.0

PROFILE Interchange

COMPONENT Layering : 1
COMPONENT Layout : 2
COMPONENT PointingDeviceSensor : 1
COMPONENT Scripting : 1

Viewpoint { }

DEF TS0 TouchSensor { }

Shape {
  appearance Appearance {
    material DEF M0 Material {
      diffuseColor 0.5 0.5 0.5
    }
  }
  geometry Box {
    size 30 30 0.1
  }
}

Transform {
  translation -2.5 0 0
  children [
    DEF TSG TouchSensor { }
    Shape {
      appearance Appearance {
        material DEF MG Material {
          diffuseColor 1 0.2 0.2
        }
      }
      geometry Sphere {
        radius 1.5
      }
    }
    Transform {
      translation 0 -3 0
      children [
        DEF TSI TouchSensor { }
        Shape {
          appearance Appearance {
            material Material {
              diffuseColor 0.2 1 0.2
            }
          }
          geometry Box {
            size 1 1 1
          }
        }
      ]
    }
  ]
}

Transform {
  translation 2.5 0 0
  children [
    DEF TSD TouchSensor {
      enabled FALSE
    }
    Shape {
      appearance Appearance {
        material Material {
          diffuseColor 0.2 0.2 1
        }
      }
      geometry Box { }
    }
  ]
}

DEF S Script {
  inputOnly      SFTime  t0
  inputOnly      SFTime  tg
  inputOnly      SFTime  ti
  inputOutput    SFInt32 c0 0
  inputOutput    SFInt32 cg 0
  inputOutput    SFInt32 ci 0
  initializeOnly SFNode  m0 USE M0
  initializeOnly SFNode  mg USE MG

  url "javascript:
function t0 (v) { c0 = c0 + 1; m0 .diffuseColor = new SFColor (0.5, 0.5 + 0.1 * c0, 0.5); }
function tg (v) { cg = cg + 1; mg .diffuseColor = new SFColor (1, 0.2 + 0.3 * cg, 0.2); }
function ti (v) { ci = ci + 1; }
"
  directOutput TRUE
}

ROUTE TS0.touchTime TO S.t0
ROUTE TSG.touchTime TO S.tg
ROUTE TSI.touchTime TO S.ti

